SELECT [Станции_для_сводной(архив)].NAME, Пост_перем_затраты.NUMB1120 AS NUMB, [Станции_для_сводной(архив)].gruppa_oborud, Пост_перем_затраты.Year AS Years, IIf([nust]>0,[Post_Sum]/[nust],0) AS ud_post, IIf(([W]+[Qotp])>0,(([Per_E]+[Per_Q])*1000)/(([W]*1000000+[Qotp]*1162990)),0) AS ud_per, *
FROM Пост_перем_затраты LEFT JOIN [Станции_для_сводной(архив)] ON (Пост_перем_затраты.NUMB1120 = [Станции_для_сводной(архив)].numb1120) AND (Пост_перем_затраты.Year = [Станции_для_сводной(архив)].Year);
